#!/usr/bin/env bash
# ============================================================================
# seed_vc_iraqi_colab.sh - Google Colab edition (use a GPU runtime)
# In a Colab cell:   !bash seed_vc_iraqi_colab.sh
# Or piped:          !curl -fsSL <this-script-url> | bash
# ============================================================================
set -euo pipefail

echo "=========================================================================="
echo " Seed-VC Iraqi Dialect Bootstrap - data + fine-tune + export"
echo " Model: seed-uvit-tat-xlsr-tiny  (zero-shot real-time voice conversion)"
echo " Data : Iraqi-dialect speech (YODAS-IQ catalog 339h + 3 clean Iraqi sets)"
echo " All stages are resumable: re-run this script any time to continue."
echo " Env  : IRAQI_YODAS_HOURS(200|all|0) IRAQI_STEPS(3000) IRAQI_BATCH(2)"
echo "        IRAQI_SAVE_EVERY(250) IRAQI_SKIP_TRAIN=1 IRAQI_SKIP_SMALL=1"
echo "        IRAQI_RUN_NAME(iraqi_v1) IRAQI_DATA_ROOT  HF_ENDPOINT(mirror)"
echo "=========================================================================="

say()  { printf '\033[1;36m[iraqi]\033[0m %s\n' "$*"; }
fail() { printf '\033[1;31m[iraqi][ERROR]\033[0m %s\n' "$*"; exit 1; }
aptdo() {
  if [ "$(id -u)" -eq 0 ]; then apt-get -qq "$@" >/dev/null 2>&1;
  elif command -v sudo >/dev/null 2>&1; then sudo apt-get -qq "$@" >/dev/null 2>&1;
  else echo "[iraqi] (no root/sudo; skipping: apt-get $*)"; return 1; fi
}

ROOT="${IRAQI_DATA_ROOT:-/content/iraqi_seedvc}"
STEPS="${IRAQI_STEPS:-3000}"
BATCH="${IRAQI_BATCH:-2}"
SAVE_EVERY="${IRAQI_SAVE_EVERY:-250}"
YODAS_HOURS="${IRAQI_YODAS_HOURS:-200}"
RUN_NAME="${IRAQI_RUN_NAME:-iraqi_v1}"
NPROC=$(nproc 2>/dev/null || echo 4)
WORKERS="${IRAQI_WORKERS:-$NPROC}"
if [ "$WORKERS" -gt 8 ]; then WORKERS=8; fi
FW=8; T=$((NPROC * 2)); if [ "$T" -gt 16 ]; then T=16; fi; if [ "$T" -gt "$FW" ]; then FW=$T; fi
FETCH_WORKERS="${IRAQI_FETCH_WORKERS:-$FW}"

mkdir -p "$ROOT"
cd "$ROOT"

# ---------------------------------------------------------------- GPU check
GPU_OK=1
nvidia-smi >/dev/null 2>&1 || GPU_OK=0
if [ "$GPU_OK" -eq 0 ]; then
  say "WARNING: no NVIDIA GPU detected - data will be prepared, training SKIPPED."
fi

# ---------------------------------------------------------------- stage 1
say "stage 1/8: system dependencies (ffmpeg, git)"
aptdo update || true
command -v ffmpeg >/dev/null 2>&1 || aptdo install -y ffmpeg
command -v git >/dev/null 2>&1 || aptdo install -y git
command -v ffmpeg >/dev/null 2>&1 || fail "ffmpeg not available - install it and re-run"
command -v git >/dev/null 2>&1 || fail "git not available - install it and re-run"
say "  ffmpeg: $(ffmpeg -version 2>/dev/null | head -1)"

# ---------------------------------------------------------------- stage 2
say "stage 2/8: Python environment + PyTorch 2.4.0 (CUDA 12.1)"
PY=python3
$PY -m pip install -q --upgrade pip >/dev/null 2>&1 || true
if ! $PY -c "import torch; assert torch.__version__.startswith('2.4.')" >/dev/null 2>&1; then
  say "  installing pinned PyTorch 2.4.0 cu121 (about 2.5 GB) ..."
  $PY -m pip install -q torch==2.4.0 torchvision==0.19.0 torchaudio==2.4.0 \
    --index-url https://download.pytorch.org/whl/cu121 \
    || $PY -m pip install -q torch torchvision torchaudio --index-url https://download.pytorch.org/whl/cu121 \
    || fail "PyTorch install failed"
fi
$PY -m pip install -q numpy==1.26.4 scipy==1.13.1 librosa==0.10.2 soundfile==0.12.1 munch==4.0.0 einops==0.8.0 transformers==4.46.3 pyyaml tqdm requests pyarrow==17.0.0 huggingface_hub \
  || $PY -m pip install -q numpy scipy librosa soundfile munch einops transformers pyyaml tqdm requests pyarrow==17.0.0 huggingface_hub \
  || fail "python dependencies install failed"
$PY - <<'CHK'
import torch, transformers, librosa, soundfile, munch, pyarrow, huggingface_hub, yaml
print("  torch", torch.__version__, "| cuda:", torch.cuda.is_available())
CHK

# ---------------------------------------------------------------- stage 3
say "stage 3/8: Seed-VC repository"
if [ -d "$ROOT/seed-vc/.git" ]; then
  git -C "$ROOT/seed-vc" pull --ff-only 2>/dev/null || true
else
  git clone --depth 1 https://github.com/Plachtaa/seed-vc.git "$ROOT/seed-vc" \
    || fail "git clone of Seed-VC failed - check network / proxy"
fi
[ -f "$ROOT/seed-vc/train.py" ] || fail "Seed-VC repo incomplete"
SEEDVC="$ROOT/seed-vc"

# ---------------------------------------------------------------- stage 4
say "stage 4/8: writing embedded data pipeline (Iraqi manifests included)"
cat > "$ROOT/iraqi_pipeline.py" <<'PYEOF'
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
iraqi_pipeline.py — Shared data pipeline for fine-tuning Seed-VC
(seed-uvit-tat-xlsr-tiny) on Iraqi dialect speech.

Self-contained: the Iraqi clip manifest, source offsets (byte-exact ranged
fetch map into espnet/yodas3 tars) and quality ranking are embedded below as
base64+gzip blobs, generated from a full scan of
oddadmix/yodas-v3-ar-labeled (dialect='iq': 49,194 clips / 339.0 h across
2,360 source recordings) and an estimate-guided index of
espnet/yodas3/data/ar/audio/*.tar (2,308 sources resolvable = 334.4 h).

Commands
  small       download the small clean Iraqi speech sets (HF parquet/wav)
  yodas       ranged-fetch selected Iraqi source recordings from espnet tars
  prep        cut + segment + encode all raw audio -> training folder
  stats       report processed data statistics
  prefetch    pre-download all checkpoints needed by seed-vc train.py
  export      package fine-tuned weights + config + report
  verify      smoke-test: run inference.py with the fine-tuned checkpoint

All stages are resumable (done-markers / skip-existing) and log progress.
"""
import os, sys, json, gzip, base64, time, random, argparse, subprocess, shutil
from concurrent.futures import ThreadPoolExecutor, as_completed

# ---------------------------------------------------------------------------
# Embedded manifests (generated 2026-11; source datasets are static archives)
# ---------------------------------------------------------------------------
_IQ_CLIPS_B64 = r""""""
_IQ_OFFS_B64 = r""""""
_IQ_SRC_B64 = r""""""

def _b64gz(s):
    return json.loads(gzip.decompress(base64.b64decode(s)))

CLIPS = _b64gz(_IQ_CLIPS_B64) if not _IQ_CLIPS_B64.startswith("@@") else []
OFFS = _b64gz(_IQ_OFFS_B64) if not _IQ_OFFS_B64.startswith("@@") else {}
SRCRANK = _b64gz(_IQ_SRC_B64) if not _IQ_SRC_B64.startswith("@@") else {}

# clips by source id
CLIPS_BY_SID = {}
for c in CLIPS:
    CLIPS_BY_SID.setdefault(c["sid"], []).append(c)
for sid in CLIPS_BY_SID:
    CLIPS_BY_SID[sid].sort(key=lambda c: c["st"])

TOTAL_CLIP_HOURS = sum(c["du"] for c in CLIPS) / 3600.0

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def log(msg):
    print(f"[iraqi] {msg}", flush=True)

def hf_url(path):
    """build a resolve URL honoring HF_ENDPOINT (mirror support)"""
    host = os.environ.get("HF_ENDPOINT", "https://huggingface.co").rstrip("/")
    return f"{host}/datasets/espnet/yodas3/resolve/main/{path}"

def http_session():
    import requests
    s = requests.Session()
    s.headers.update({"User-Agent": "seed-vc-iraqi-bootstrap/1.0"})
    return s

def fetch_range(sess, url, start, end, retries=4, timeout=600):
    for a in range(retries):
        try:
            r = sess.get(url, headers={"Range": f"bytes={start}-{end}"}, timeout=timeout)
            if r.status_code in (200, 206) and len(r.content) == end - start + 1:
                return r.content
        except Exception:
            pass
        time.sleep(min(30, 2 ** a) + random.random() * 2)
    return None

def ffmpeg():
    return os.environ.get("IRAQI_FFMPEG", "ffmpeg")

def ffprobe_dur(path):
    exe = os.environ.get("IRAQI_FFPROBE", "ffprobe")
    try:
        out = subprocess.run([exe, "-v", "error", "-show_entries", "format=duration",
                              "-of", "csv=p=0", path], capture_output=True, text=True, timeout=60)
        return float(out.stdout.strip())
    except Exception:
        return None

def encode_clip(src, ss, t, out):
    """cut [ss, ss+t] from src -> 24 kHz mono opus/ogg (Seed-VC loads at 22050)"""
    os.makedirs(os.path.dirname(out), exist_ok=True)
    cmd = [ffmpeg(), "-v", "error", "-y"]
    if ss is not None:
        cmd += ["-ss", f"{ss:.3f}"]
    cmd += ["-i", src]
    if t is not None:
        cmd += ["-t", f"{t:.3f}"]
    cmd += ["-ac", "1", "-ar", "24000", "-c:a", "libopus", "-b:a", "28k", out]
    p = subprocess.run(cmd, capture_output=True, text=True)
    return p.returncode == 0 and os.path.exists(out) and os.path.getsize(out) > 1024

def done_marker(root, name):
    return os.path.join(root, ".done", name + ".done")

def mark_done(root, name):
    os.makedirs(os.path.join(root, ".done"), exist_ok=True)
    open(done_marker(root, name), "w").write(time.strftime("%Y-%m-%d %H:%M:%S"))

def is_done(root, name):
    return os.path.exists(done_marker(root, name))

# ---------------------------------------------------------------------------
# small datasets (clean Iraqi speech)
# ---------------------------------------------------------------------------
SMALL_SETS = {
    "youssef": {
        "repo": "xtz999/iraqi_arabic_speech_youssef",
        "files": ["data/train-00000-of-00002.parquet", "data/train-00001-of-00002.parquet"],
        "about": "3,867 Iraqi clips @22.05 kHz with transcripts (~720 MB)",
    },
    "shiekh": {
        "repo": "karimBD/Iraqi_shiekh_hara_sawtarabi_MediaSpeech",
        "files": ["data/train-00000-of-00002.parquet", "data/train-00001-of-00002.parquet"],
        "about": "827 Iraqi clips @16 kHz (single religious speaker, ~640 MB)",
    },
}
SAFAA_REPO = "safaa94/Myvoice-iraqi-accent-samples"

def _sniff_ext(data, path=""):
    """guess audio extension from magic bytes / provided path"""
    p = (path or "").lower()
    for e in (".wav", ".mp3", ".flac", ".ogg", ".opus", ".m4a", ".webm"):
        if p.endswith(e):
            return e
    if data[:4] == b"RIFF":
        return ".wav"
    if data[:3] == b"ID3" or (len(data) > 2 and data[0] == 0xFF and (data[1] & 0xE0) == 0xE0):
        return ".mp3"
    if data[:4] == b"OggS":
        return ".ogg"
    if data[:4] == b"fLaC":
        return ".flac"
    if data[:4] == b"\x1aE\xdf\xa3":
        return ".webm"
    if data[4:8] == b"ftyp":
        return ".m4a"
    return ".bin"

def _iter_parquet_audio(path, outdir, prefix, part):
    """yield (index, bytes, ext) from a HF parquet containing an audio column.
    `part` keeps names unique across multiple parquet files."""
    import pyarrow.parquet as pq
    tbl = pq.read_table(path)
    cols = tbl.schema.names
    audio_col = None
    for cand in ("audio", "Audio"):
        if cand in cols:
            audio_col = cand
            break
    if audio_col is None:
        raise RuntimeError(f"no audio column in {path} (cols={cols})")
    col = tbl.column(audio_col).to_pylist()
    for i, v in enumerate(col):
        if v is None:
            continue
        data, spath = None, ""
        if isinstance(v, dict):
            data = v.get("bytes")
            spath = v.get("path") or ""
        elif isinstance(v, (bytes, bytearray)):
            data = bytes(v)
        if not data:
            continue
        ext = _sniff_ext(data, spath)
        if ext == ".bin":
            continue
        yield f"{prefix}_p{part}_{i:06d}{ext}", data

def cmd_small(args):
    root = args.root
    os.makedirs(root, exist_ok=True)
    from huggingface_hub import hf_hub_download, snapshot_download
    todo = args.only or ["youssef", "shiekh", "safaa"]
    for name in todo:
        if name not in todo:
            continue
        if is_done(root, f"small_{name}"):
            log(f"small/{name}: already done, skipping")
            continue
        outdir = os.path.join(root, "raw", name)
        os.makedirs(outdir, exist_ok=True)
        if name in SMALL_SETS:
            info = SMALL_SETS[name]
            log(f"small/{name}: {info['about']} <- {info['repo']}")
            pqdir = os.path.join(root, "raw", "_parquet", name)
            for part, f in enumerate(info["files"]):
                p = hf_hub_download(repo_id=info["repo"], filename=f,
                                    repo_type="dataset", local_dir=pqdir)
                cnt = 0
                for fn, data in _iter_parquet_audio(p, outdir, name, part):
                    dst = os.path.join(outdir, fn)
                    if not os.path.exists(dst):
                        open(dst, "wb").write(data)
                    cnt += 1
                log(f"small/{name}: {cnt} clips from {os.path.basename(p)}")
        elif name == "safaa":
            log(f"small/safaa: 676 Iraqi wavs (single female speaker, TTS-ready chunks)")
            snapshot_download(repo_id=SAFAA_REPO, repo_type="dataset",
                              local_dir=os.path.join(root, "raw", "_safaa_src"),
                              allow_patterns=["train/*", "test/*"])
            src_dir = os.path.join(root, "raw", "_safaa_src")
            cnt = 0
            for sub in ("train", "test"):
                d = os.path.join(src_dir, sub)
                if not os.path.isdir(d):
                    continue
                for fn in os.listdir(d):
                    if fn.lower().endswith(".wav"):
                        dst = os.path.join(outdir, f"{sub}_{fn}")
                        if not os.path.exists(dst):
                            shutil.copyfile(os.path.join(d, fn), dst)
                        cnt += 1
            log(f"small/safaa: {cnt} wav files")
        mark_done(root, f"small_{name}")
    log("small: complete")

# ---------------------------------------------------------------------------
# YODAS Iraqi ranged fetch
# ---------------------------------------------------------------------------
def select_sources(hours, limit):
    """pick best-quality sources until `hours` of Iraqi clips are covered"""
    ranked = sorted(SRCRANK.items(), key=lambda kv: -kv[1][2])  # by quality desc
    chosen, h = [], 0.0
    for sid, (tar, ch, q) in ranked:
        if sid not in OFFS or OFFS[sid].get("off") is None:
            continue
        chosen.append(sid)
        h += ch
        if hours and h >= hours:
            break
        if limit and len(chosen) >= limit:
            break
    return chosen, h

def cmd_yodas(args):
    root = args.root
    os.makedirs(root, exist_ok=True)
    hours = None if args.hours in (None, "all", "ALL", "0") else float(args.hours)
    if args.hours in (None, "all", "ALL") and args.hours != "0":
        hours = None
    chosen, est_h = select_sources(hours, args.limit)
    webm_dir = os.path.join(root, "raw", "yodas_webm")
    os.makedirs(webm_dir, exist_ok=True)
    log(f"yodas: {len(chosen)} source recordings selected (~{est_h:.1f} h of Iraqi clips, "
        f"~{sum(OFFS[s]['size'] for s in chosen)/1e9:.1f} GB to fetch from espnet/yodas3)")

    sess = http_session()
    state_path = os.path.join(root, "raw", "yodas_fetch_state.json")
    state = {"failed": []}
    if os.path.exists(state_path):
        state = json.load(open(state_path))

    def fetch_one(sid):
        v = OFFS[sid]
        out = os.path.join(webm_dir, f"{sid}.webm")
        if os.path.exists(out) and os.path.getsize(out) == v["size"]:
            return sid, "skip"
        url = hf_url(f"data/ar/audio/{v['tar']:04d}.tar")
        data = fetch_range(sess, url, int(v["off"]), int(v["off"]) + int(v["size"]) - 1)
        if data is None:
            return sid, "fail"
        open(out, "wb").write(data)
        return sid, "ok"

    ok = skip = fail = 0
    t0 = time.time()
    with ThreadPoolExecutor(max_workers=args.workers) as ex:
        futs = {ex.submit(fetch_one, s): s for s in chosen}
        for n, fut in enumerate(as_completed(futs), 1):
            sid, res = fut.result()
            if res == "ok":
                ok += 1
            elif res == "skip":
                skip += 1
            else:
                fail += 1
                state["failed"].append(sid)
            if n % 25 == 0 or n == len(chosen):
                el = time.time() - t0
                got = (ok + skip)
                log(f"yodas: {n}/{len(chosen)} | fetched {ok} | cached {skip} | failed {fail} | "
                    f"{el:.0f}s | ~{got*args.workers*60/max(el,1)/args.workers/60:.1f}/min")
    state["failed"] = sorted(set(state["failed"]))
    json.dump(state, open(state_path, "w"))
    log(f"yodas: done | fetched {ok} new | cached {skip} | failed {fail} "
        f"(failed sources are skipped; Iraqi clips from them are excluded)")
    mark_done(root, f"yodas_{args.hours}")

# ---------------------------------------------------------------------------
# preprocessing (cut / segment / encode)
# ---------------------------------------------------------------------------
def _prep_job_src(args, src_path, origin):
    """yield (src, ss, t, out) jobs"""
    out_root = args.out
    if origin == "yodas":
        sid = os.path.basename(src_path).rsplit(".", 1)[0]
        clips = CLIPS_BY_SID.get(sid)
        if not clips:
            return
        # merge adjacent windows (gap < 0.5 s)
        merged = []
        for c in clips:
            if merged and c["st"] - merged[-1][1] < 0.5:
                merged[-1][1] = max(merged[-1][1], c["en"])
            else:
                merged.append([max(0.0, c["st"]), c["en"]])
        k = 0
        for st, en in merged:
            dur = en - st
            if dur < 1.5:
                continue
            pos = st
            while pos < en - 0.2:
                t = min(29.5, en - pos)
                if t < 1.5:
                    break
                out = os.path.join(out_root, "yodas", f"{sid}__{k:04d}.ogg")
                yield (src_path, pos, t, out)
                k += 1
                pos += t
    else:
        d = ffprobe_dur(src_path)
        if d is None or d < 1.5:
            return
        import hashlib, re
        fn = os.path.basename(src_path)
        h = hashlib.md5(fn.encode("utf-8", "ignore")).hexdigest()[:10]
        stem = re.sub(r"[^0-9A-Za-z_.-]+", "_", os.path.splitext(fn)[0])[:40].strip("_") or "clip"
        base = f"{stem}_{h}"
        pos, k = 0.0, 0
        while pos < d - 0.2:
            t = min(29.5, d - pos)
            if t < 1.5:
                break
            out = os.path.join(out_root, origin, f"{base}__{k:04d}.ogg")
            yield (src_path, pos, t, out)
            k += 1
            pos += t

def _run_prep_job(job):
    src, ss, t, out = job
    if os.path.exists(out) and os.path.getsize(out) > 1024:
        return (out, t, True)
    okk = encode_clip(src, ss, t, out)
    return (out, t, okk)

def cmd_prep(args):
    root = args.root
    raw = os.path.join(root, "raw")
    index_path = os.path.join(args.out, "_prep_index.jsonl")
    os.makedirs(args.out, exist_ok=True)
    jobs = []
    if not args.skip_yodas:
        ydir = os.path.join(raw, "yodas_webm")
        if os.path.isdir(ydir):
            for fn in os.listdir(ydir):
                if fn.endswith(".webm"):
                    jobs.extend(_prep_job_src(args, os.path.join(ydir, fn), "yodas"))
    small_files = []
    for origin in ("youssef", "shiekh", "safaa"):
        d = os.path.join(raw, origin)
        if os.path.isdir(d):
            for fn in sorted(os.listdir(d)):
                if fn.lower().endswith((".wav", ".mp3", ".flac", ".ogg", ".opus", ".m4a", ".webm")):
                    small_files.append((os.path.join(d, fn), origin))
    if small_files:
        log(f"prep: probing {len(small_files)} small-set files (parallel) ...")
        with ThreadPoolExecutor(max_workers=16) as ex:
            for jl in ex.map(lambda x: list(_prep_job_src(args, *x)), small_files):
                jobs.extend(jl)
    if args.limit:
        jobs = jobs[:args.limit]
    log(f"prep: {len(jobs)} encode jobs -> {args.out}")
    from multiprocessing import Pool
    t0, done_ok, done_skip, done_fail = time.time(), 0, 0, 0
    with Pool(processes=args.workers) as pool:
        for n, (out, t, okk) in enumerate(pool.imap_unordered(_run_prep_job, jobs, chunksize=16), 1):
            if okk and os.path.exists(out) and os.path.getsize(out) > 1024:
                done_ok += 1
            else:
                done_fail += 1
            if n % 200 == 0 or n == len(jobs):
                el = time.time() - t0
                rate = n / max(el, 1)
                log(f"prep: {n}/{len(jobs)} | ok {done_ok} | fail {done_fail} | "
                    f"{rate:.1f}/s | eta {(len(jobs)-n)/max(rate,0.01):.0f}s")
    # rebuild index of produced files: merge with previous index (dedupe by file)
    log("prep: indexing outputs ...")
    prev = {}
    if os.path.exists(index_path):
        for line in open(index_path):
            try:
                r = json.loads(line)
                prev[r["file"]] = r["dur"]
            except Exception:
                pass
    for j in jobs:
        prev[os.path.relpath(j[3], args.out)] = j[2]
    # also drop entries whose files disappeared
    prev = {f: d for f, d in prev.items() if os.path.exists(os.path.join(args.out, f))}
    with open(index_path, "w") as fh:
        for fn_, d_ in sorted(prev.items()):
            fh.write(json.dumps({"file": fn_, "dur": d_}) + "\n")
    mark_done(root, f"prep_{os.path.basename(os.path.normpath(args.out))}")
    cmd_stats(args)

def cmd_stats(args):
    d = args.out if hasattr(args, "out") and os.path.isdir(str(args.out)) else args.dir
    index = os.path.join(d, "_prep_index.jsonl")
    per, tot_h, tot_n = {}, 0.0, 0
    if os.path.exists(index):
        for line in open(index):
            try:
                r = json.loads(line)
            except Exception:
                continue
            if not os.path.exists(os.path.join(d, r["file"])):
                continue
            src = r["file"].split(os.sep)[0]
            per.setdefault(src, [0, 0.0])
            per[src][0] += 1
            per[src][1] += r["dur"] / 3600
            tot_n += 1
            tot_h += r["dur"] / 3600
    log("=== processed training data ===")
    for k in sorted(per):
        log(f"  {k:10s}: {per[k][0]:6d} files | {per[k][1]:7.2f} h")
    log(f"  TOTAL     : {tot_n:6d} files | {tot_h:7.2f} h")
    json.dump({"total_files": tot_n, "total_hours": round(tot_h, 3),
               "per_source": {k: {"files": v[0], "hours": round(v[1], 3)} for k, v in per.items()}},
              open(os.path.join(d, "_stats.json"), "w"), indent=2)

# ---------------------------------------------------------------------------
# checkpoint prefetch
# ---------------------------------------------------------------------------
PREFETCH = [
    ("Plachta/Seed-VC", "model", "DiT_uvit_tat_xlsr_ema.pth"),
    ("Plachta/Seed-VC", "model", "se_db.pt"),
    ("funasr/campplus", "model", "campplus_cn_common.bin"),
    ("myshell-ai/OpenVoiceV2", "model", "converter/checkpoint.pth"),
    ("myshell-ai/OpenVoiceV2", "model", "converter/config.json"),
    ("FunAudioLLM/CosyVoice-300M", "model", "hift.pt"),
]

def cmd_prefetch(args):
    repo = args.repo
    os.environ["HF_HUB_CACHE"] = os.path.join(repo, "checkpoints", "hf_cache")
    from huggingface_hub import hf_hub_download, snapshot_download
    for repo_id, rtype, fn in PREFETCH:
        for a in range(3):
            try:
                p = hf_hub_download(repo_id=repo_id, filename=fn, repo_type=rtype,
                                    cache_dir=os.path.join(repo, "checkpoints"))
                log(f"prefetch: {repo_id}/{fn} -> {p}")
                break
            except Exception as e:
                log(f"prefetch retry {a+1} for {repo_id}/{fn}: {e}")
                time.sleep(3)
    for a in range(3):
        try:
            p = snapshot_download("facebook/wav2vec2-xls-r-300m",
                                  cache_dir=os.path.join(repo, "checkpoints", "hf_cache"))
            log(f"prefetch: facebook/wav2vec2-xls-r-300m -> {p}")
            break
        except Exception as e:
            log(f"prefetch retry {a+1} for wav2vec2-xls-r-300m: {e}")
            time.sleep(3)

# ---------------------------------------------------------------------------
# export fine-tuned weights
# ---------------------------------------------------------------------------
def cmd_export(args):
    src = args.run_dir
    ft = os.path.join(src, "ft_model.pth")
    if not os.path.exists(ft):
        log(f"export: ft_model.pth not found in {src} — did training finish?")
        sys.exit(1)
    ts = time.strftime("%Y%m%d_%H%M%S")
    out = args.out or os.path.join(os.path.dirname(src), "iraqi_seed_vc_tiny_" + ts)
    os.makedirs(out, exist_ok=True)
    shutil.copyfile(ft, os.path.join(out, "seed_uvit_tat_xlsr_tiny_iraqi.pth"))
    cfg = os.path.join(src, os.path.basename(args.config))
    if not os.path.exists(cfg):
        cfg = args.config
    shutil.copyfile(cfg, os.path.join(out, "config_dit_mel_seed_uvit_xlsr_tiny.yml"))
    stats_path = os.path.join(args.data_dir, "_stats.json")
    stats = json.load(open(stats_path)) if os.path.exists(stats_path) else {}
    report = {
        "exported_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "base_model": "seed-uvit-tat-xlsr-tiny (Plachta/Seed-VC DiT_uvit_tat_xlsr_ema.pth)",
        "task": "Iraqi dialect adaptation fine-tune",
        "run_dir": os.path.abspath(src),
        "training_data": stats,
        "original_manifest": {
            "iraqi_clips_total": len(CLIPS),
            "iraqi_hours_total": round(TOTAL_CLIP_HOURS, 1),
            "sources_resolvable": len([1 for v in OFFS.values() if v.get("off")]),
        },
    }
    json.dump(report, open(os.path.join(out, "training_report.json"), "w"),
              indent=2, ensure_ascii=False)
    readme = f"""# Seed-VC Iraqi — fine-tuned seed-uvit-tat-xlsr-tiny
Exported: {report['exported_at']}

Weights : seed_uvit_tat_xlsr_tiny_iraqi.pth
Config  : config_dit_mel_seed_uvit_xlsr_tiny.yml
Report  : training_report.json

## الاستخدام (Usage)
python inference.py \\
  --checkpoint {os.path.abspath(os.path.join(out, 'seed_uvit_tat_xlsr_tiny_iraqi.pth'))} \\
  --config     {os.path.abspath(os.path.join(out, 'config_dit_mel_seed_uvit_xlsr_tiny.yml'))} \\
  --source <wav> --target <reference-wav> --output ./out

Web UI:
python app_vc.py --checkpoint <above .pth> --config <above .yml>
"""
    open(os.path.join(out, "README.md"), "w").write(readme)
    log(f"export: packaged model -> {out}")
    print(out)

# ---------------------------------------------------------------------------
# verify (smoke test with fine-tuned checkpoint)
# ---------------------------------------------------------------------------
def cmd_verify(args):
    repo = args.repo
    ref_dir = os.path.join(args.data_dir, "yodas")
    ref = None
    if os.path.isdir(ref_dir):
        for fn in sorted(os.listdir(ref_dir))[:5]:
            if fn.endswith(".ogg"):
                ref = os.path.join(ref_dir, fn)
                break
    src = os.path.join(repo, "examples", "source", "source_s1.wav")
    if not os.path.exists(src):
        for fn in sorted(os.listdir(os.path.join(repo, "examples", "source"))):
            src = os.path.join(repo, "examples", "source", fn)
            break
    if not ref:
        log("verify: no processed Iraqi clip found to use as reference; skipping")
        return 0
    outdir = os.path.join(args.run_dir, "verify_out")
    os.makedirs(outdir, exist_ok=True)
    cmd = [sys.executable, "inference.py",
           "--checkpoint", os.path.abspath(args.ckpt),
           "--config", os.path.abspath(args.config),
           "--source", os.path.abspath(src),
           "--target", os.path.abspath(ref),
           "--output", os.path.abspath(outdir),
           "--diffusion-steps", "16", "--fp16", "true"]
    log(f"verify: {' '.join(cmd[1:])}")
    p = subprocess.run(cmd, cwd=repo)
    if p.returncode == 0:
        log("verify: OK — fine-tuned checkpoint produces converted audio")
        return 0
    log("verify: inference returned non-zero (see log above)")
    return 1

# ---------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("small")
    p.add_argument("--root", default="iraqi_seedvc")
    p.add_argument("--only", nargs="*", choices=["youssef", "shiekh", "safaa"])
    p.set_defaults(fn=cmd_small)

    p = sub.add_parser("yodas")
    p.add_argument("--root", default="iraqi_seedvc")
    p.add_argument("--hours", default="200")
    p.add_argument("--workers", type=int, default=8)
    p.add_argument("--limit", type=int, default=None)
    p.set_defaults(fn=cmd_yodas)

    p = sub.add_parser("prep")
    p.add_argument("--root", default="iraqi_seedvc")
    p.add_argument("--out", default="iraqi_seedvc/data/iraqi_finetune")
    p.add_argument("--workers", type=int, default=8)
    p.add_argument("--skip-yodas", action="store_true")
    p.add_argument("--limit", type=int, default=None)
    p.set_defaults(fn=cmd_prep)

    p = sub.add_parser("stats")
    p.add_argument("--dir", default="iraqi_seedvc/data/iraqi_finetune")
    p.set_defaults(fn=cmd_stats)

    p = sub.add_parser("prefetch")
    p.add_argument("--repo", default="seed-vc")
    p.set_defaults(fn=cmd_prefetch)

    p = sub.add_parser("export")
    p.add_argument("--run-dir", required=True)
    p.add_argument("--config", default="configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml")
    p.add_argument("--data-dir", default="iraqi_seedvc/data/iraqi_finetune")
    p.add_argument("--out", default=None)
    p.set_defaults(fn=cmd_export)

    p = sub.add_parser("verify")
    p.add_argument("--repo", default="seed-vc")
    p.add_argument("--run-dir", required=True)
    p.add_argument("--ckpt", required=True)
    p.add_argument("--config", default="configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml")
    p.add_argument("--data-dir", default="iraqi_seedvc/data/iraqi_finetune")
    p.set_defaults(fn=cmd_verify)

    args = ap.parse_args()
    rc = args.fn(args)
    sys.exit(rc or 0)

if __name__ == "__main__":
    main()

PYEOF
"$PY" -c "import ast; ast.parse(open('$ROOT/iraqi_pipeline.py').read())" \
  || fail "embedded pipeline is corrupted"
PIPE="$ROOT/iraqi_pipeline.py"

# ---------------------------------------------------------------- stage 5
if [ "${IRAQI_SKIP_SMALL:-0}" != "1" ]; then
  say "stage 5/8: downloading clean Iraqi speech sets (youssef / shiekh / safaa)"
  "$PY" "$PIPE" small --root "$ROOT" || fail "small datasets stage failed"
else
  say "stage 5/8: skipped (IRAQI_SKIP_SMALL=1)"
fi

# ---------------------------------------------------------------- stage 6
if [ "$YODAS_HOURS" != "0" ]; then
  say "stage 6/8: ranged-fetching Iraqi speech from espnet/yodas3 (target: ${YODAS_HOURS}h)"
  "$PY" "$PIPE" yodas --root "$ROOT" --hours "$YODAS_HOURS" --workers "$FETCH_WORKERS" \
    || fail "yodas fetch stage failed (re-run to resume)"
else
  say "stage 6/8: skipped (IRAQI_YODAS_HOURS=0)"
fi

# ---------------------------------------------------------------- stage 7
say "stage 7/8: cutting + segmenting + encoding training data (24 kHz mono opus)"
"$PY" "$PIPE" prep --root "$ROOT" --out "$ROOT/data/iraqi_finetune" --workers "$WORKERS" \
  || fail "preprocessing stage failed (re-run to resume)"
DATA_DIR="$ROOT/data/iraqi_finetune"
NFILES=$(find "$DATA_DIR" -name "*.ogg" 2>/dev/null | wc -l)
say "  training corpus: $NFILES clips ready"
[ "$NFILES" -ge 50 ] || fail "too few training clips ($NFILES) - check the logs above"

# ---------------------------------------------------------------- stage 8
RUN_DIR="$SEEDVC/runs/$RUN_NAME"
if [ "${IRAQI_SKIP_TRAIN:-0}" = "1" ]; then
  say "stage 8/8: training skipped (IRAQI_SKIP_TRAIN=1) - data ready at $DATA_DIR"
elif [ "$GPU_OK" -eq 0 ]; then
  say "stage 8/8: training skipped (no NVIDIA GPU) - data ready at $DATA_DIR"
elif [ -f "$RUN_DIR/ft_model.pth" ]; then
  say "stage 8/8: fine-tuned model already exists at $RUN_DIR/ft_model.pth (skip training)"
else
  say "stage 8/8: fine-tuning seed-uvit-tat-xlsr-tiny on Iraqi speech"
  say "  prefetching model checkpoints (DiT tiny / XLSR / OpenVoice / HiFT / CAMPPlus) ..."
  "$PY" "$PIPE" prefetch --repo "$SEEDVC" || true
  if ls "$RUN_DIR"/DiT_epoch_*.pth >/dev/null 2>&1; then
    say "  resuming from the latest rolling checkpoint in $RUN_DIR"
  else
    say "  fresh run: base weights auto-download from Plachta/Seed-VC"
  fi
  cd "$SEEDVC"
  "$PY" train.py \
    --config configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml \
    --dataset-dir "$DATA_DIR" \
    --run-name "$RUN_NAME" \
    --batch-size "$BATCH" \
    --max-steps "$STEPS" \
    --save-every "$SAVE_EVERY" \
    --num-workers 2 \
    --gpu 0 || { cd "$ROOT"; fail "training failed - re-run the script to resume from the last checkpoint"; }
  cd "$ROOT"
  say "  verifying fine-tuned checkpoint with a real inference pass ..."
  "$PY" "$PIPE" verify --repo "$SEEDVC" --run-dir "$RUN_DIR" \
    --ckpt "$RUN_DIR/ft_model.pth" \
    --config "$SEEDVC/configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml" \
    --data-dir "$DATA_DIR" || say "  (verify could not run - weights are still exported)"
fi

# ---------------------------------------------------------------- export
EXPORT_PATH=""
if [ -f "$RUN_DIR/ft_model.pth" ]; then
  say "exporting fine-tuned weights + config + report ..."
  EXPORT_PATH=$("$PY" "$PIPE" export --run-dir "$RUN_DIR" \
    --config "$SEEDVC/configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml" \
    --data-dir "$DATA_DIR" | tail -1) || EXPORT_PATH=""
  if [ -n "$EXPORT_PATH" ] && [ -d "$EXPORT_PATH" ]; then
    say "EXPORTED MODEL: $EXPORT_PATH"
    # Colab: persist to Google Drive if mounted
    if [ -d /content/drive/MyDrive ]; then
      say "  copying model to Google Drive (SeedVC_Iraqi/) ..."
      mkdir -p /content/drive/MyDrive/SeedVC_Iraqi
      cp -r "$EXPORT_PATH" /content/drive/MyDrive/SeedVC_Iraqi/ 2>/dev/null || true
    else
      say "  tip: mount Google Drive from the Colab sidebar, then re-run to copy the model there"
    fi
  fi
fi

say "ALL DONE."
if [ -n "$EXPORT_PATH" ]; then
  say "  - data      : $DATA_DIR"
  say "  - weights   : $EXPORT_PATH"
  say "  - inference : cd $SEEDVC && $PY inference.py --checkpoint <weights>/seed_uvit_tat_xlsr_tiny_iraqi.pth --config <weights>/config_dit_mel_seed_uvit_xlsr_tiny.yml --source a.wav --target b.wav --output out"
fi
